/** One gate shared by the map, its named accessibility actions and the region cards. */
internal class CountryMapSelection(
    private val animate: State<Boolean>,
    private val open: State<(Region) -> Unit>,
) {
    var region: Region? by mutableStateOf(null)
        private set
    var pressed: Region? by mutableStateOf(null)
        private set
    var dispatched by mutableStateOf(false)
        private set
    val lift = Animatable(0f)
    val busy: Boolean get() = region != null

    fun press(value: Region?) {
        if (!busy) pressed = value.takeIf { animate.value }
    }

    fun select(value: Region): Boolean {
        if (busy) return false
        pressed = null
        region = value // Lock synchronously, before any suspension or another pointer event.
        if (!animate.value) dispatch()
        return true
    }

    fun dispatch() {
        val target = region ?: return
        if (dispatched) return
        dispatched = true // Set before invoking app code, including a synchronous recomposition.
        open.value(target)
    }
}

@Composable
internal fun rememberCountryMapSelection(onSelect: (Region) -> Unit): CountryMapSelection {
    val animate = rememberUpdatedState(LocalMotionPolicy.current.canAnimate)
    val open = rememberUpdatedState(onSelect)
    val selection = remember { CountryMapSelection(animate, open) }
    val lifecycle = LocalLifecycleOwner.current.lifecycle
    val lifecycleState by lifecycle.currentStateFlow.collectAsState()
    LaunchedEffect(selection.region, animate.value, lifecycleState) {
        if (selection.region == null || selection.dispatched) return@LaunchedEffect
        if (!animate.value) {
            selection.dispatch() // Policy changes cancel a pending animation and open just once.
        } else if (lifecycleState.isAtLeast(Lifecycle.State.STARTED)) {
            // Animatable also respects the system MotionDurationScale (zero completes immediately).
            selection.lift.animateTo(1f, tween(280, easing = FastOutSlowInEasing))
            selection.dispatch()
        }
    }
    return selection
}

/** Geographic labels use the unchanged world coordinates; small city lettering stays beside its dot. */
@Composable
internal fun AtlasCountryMap(
    regions: List<RegionUi>,
    onSelect: (Region) -> Unit,
    modifier: Modifier = Modifier,
    selection: CountryMapSelection = rememberCountryMapSelection(onSelect),
) {
    val colors = GgfTheme.colors
    val known = remember(regions) { regions.associateBy { it.region } }
    val density = LocalDensity.current
    val textPx = with(density) { 20.sp.toPx() }
    val dp = density.density
    val paint = remember(textPx) {
        Paint(Paint.ANTI_ALIAS_FLAG).apply {
            textSize = textPx
            textAlign = Paint.Align.CENTER
            typeface = Typeface.create(Typeface.DEFAULT, 900, false)
        }
    }
    val drawPaint = remember { Paint(Paint.ANTI_ALIAS_FLAG) }
    var viewport by remember { mutableStateOf(IntSize.Zero) }
    val layout = remember(viewport, textPx, dp, known.keys) {
        countryLayout(viewport.width.toFloat(), viewport.height.toFloat(), paint, dp, known.keys)
    }
    val latestLayout = rememberUpdatedState(layout)
    val labelInk = if (colors.isDark) Color(0xFFF3F5EE) else Color(0xFF193B32)
    val labelPaper = if (colors.isDark) Color(0xFF102A39) else Color.White
    val canAnimate = LocalMotionPolicy.current.canAnimate
    var showSources by remember { mutableStateOf(false) }
    val zoom = density.fontScale.coerceAtLeast(1f)
    val horizontal = rememberScrollState()
    val vertical = rememberScrollState()
    Column(modifier) {
        if (zoom > 1f) Text("지도를 밀어서 둘러보세요", color = colors.ink, fontSize = 12.sp)
        BoxWithConstraints(Modifier.fillMaxWidth().weight(1f)) {
            val contentWidth = maxWidth * zoom
            // Large text expands the geographic surface too; pan instead of squeezing names.
            val contentHeight = (if (zoom > 1f) maxOf(maxHeight, 440.dp) else maxHeight) * zoom
            LaunchedEffect(contentWidth, maxWidth) {
                horizontal.scrollTo(with(density) { ((contentWidth - maxWidth) / 2).roundToPx() })
            }
            androidx.compose.foundation.layout.Box(
                Modifier.horizontalScroll(horizontal).verticalScroll(vertical),
            ) {
                Canvas(
                    Modifier.size(contentWidth, contentHeight).onSizeChanged { viewport = it }
                        .semantics {
                            role = Role.Image
                            contentDescription = "우리나라 17개 시·도 도감 선택 지도. 지역 위 이름이나 큰 지역 카드로 골라요."
                            customActions = regions.map { item ->
                                CustomAccessibilityAction("${item.region.label} 도감 열기, ${item.owned} / ${item.total}곳") {
                                    selection.select(item.region)
                                }
                            }
                        }
                        .pointerInput(regions, textPx, dp) {
                            fun hit(tap: Offset): Region? = countryHit(tap, latestLayout.value, known.keys, dp)
                            detectTapGestures(
                                onPress = { tap ->
                                    selection.press(hit(tap))
                                    try { tryAwaitRelease() } finally { selection.press(null) }
                                },
                                onTap = { tap -> hit(tap)?.let { selection.select(it) } },
                            )
                        },
                ) {
                    drawRoundRect(colors.skySoft, cornerRadius = CornerRadius(20.dp.toPx()))
                    val transform = layout.transform
                    if (transform.scale <= 0f) return@Canvas
                    val selected = selection.region ?: selection.pressed
                    val progress = if (!canAnimate || selected == null) 0f
                        else if (selection.region != null) max(.12f, selection.lift.value) else .12f
                    val liftPx = 16.dp.toPx() * progress
                    fun fill(shape: CountryShape): Color = when {
                        known[shape.region]?.complete == true -> colors.forest
                        colors.isDark -> shape.color.copy(alpha = .55f)
                        else -> shape.color
                    }
                    withTransform({
                        translate(transform.offset.x, transform.offset.y)
                        scale(transform.scale, transform.scale, Offset.Zero)
                        translate(-transform.origin.x, -transform.origin.y)
                    }) {
                        CountryShapes.forEach { shape ->
                            if (shape.region != selected || progress == 0f) {
                                drawPath(shape.path, fill(shape))
                                drawPath(shape.path, colors.ink2, style = Stroke(dp / transform.scale))
                            }
                        }
                        CountryShapes.firstOrNull { it.region == selected }?.takeIf { progress > 0f }?.let { shape ->
                            val scaleUp = 1f + .045f * progress
                            withTransform({
                                translate(2f * dp / transform.scale, 5f * dp / transform.scale)
                                scale(scaleUp, scaleUp, shape.anchor)
                            }) { drawPath(shape.path, Color.Black.copy(alpha = .22f * progress)) }
                            withTransform({
                                translate(0f, -(liftPx - 4f * dp * progress) / transform.scale)
                                scale(scaleUp, scaleUp, shape.anchor)
                            }) { drawPath(shape.path, lerp(fill(shape), labelInk, .25f)) }
                            withTransform({
                                translate(0f, -liftPx / transform.scale)
                                scale(scaleUp, scaleUp, shape.anchor)
                            }) {
                                drawPath(shape.path, lerp(fill(shape), Color.White, .20f))
                                drawPath(shape.path, labelInk, style = Stroke(1.5f * dp / transform.scale))
                            }
                        }
                    }
                    // Province lettering first, then the nearby city lettering and geographic dots.
                    layout.labels.sortedBy { it.city }.forEach { label ->
                        if (label.city && label.shortLeader) {
                            val closest = Offset(label.dot.x.coerceIn(label.rect.left, label.rect.right),
                                label.dot.y.coerceIn(label.rect.top, label.rect.bottom))
                            drawLine(labelInk.copy(alpha = .65f), label.dot, closest, dp)
                        }
                        drawPaint.set(paint)
                        drawPaint.textSize = label.fontPx
                        drawPaint.color = labelInk.toArgb()
                        val fm = drawPaint.fontMetrics
                        val lineHeight = fm.descent - fm.ascent
                        val totalHeight = lineHeight * label.lines.size + 2f * dp * (label.lines.size - 1)
                        val firstBaseline = label.rect.center.y - totalHeight / 2 - fm.ascent
                        label.lines.forEachIndexed { index, line ->
                            drawIntoCanvas {
                                drawPaint.style = Paint.Style.STROKE
                                drawPaint.strokeJoin = Paint.Join.ROUND
                                drawPaint.strokeCap = Paint.Cap.ROUND
                                drawPaint.strokeWidth = 4f * dp * zoom
                                drawPaint.color = labelPaper.toArgb()
                                it.nativeCanvas.drawText(line, label.rect.center.x,
                                    firstBaseline + index * (lineHeight + 2f * dp), drawPaint)
                                drawPaint.style = Paint.Style.FILL
                                drawPaint.color = labelInk.toArgb()
                                it.nativeCanvas.drawText(line, label.rect.center.x,
                                    firstBaseline + index * (lineHeight + 2f * dp), drawPaint)
                            }
                        }
                        if (label.city) {
                            drawCircle(labelPaper, 4f * dp, label.dot)
                            drawCircle(labelInk, 2.5f * dp, label.dot)
                        }
                    }
                }
            }
        }
        TextButton(onClick = { showSources = true }, enabled = !selection.busy, modifier = Modifier.align(Alignment.End)) {
            Text("지도 출처 · SGIS / admdongkor", color = colors.ink, fontSize = 12.sp)
        }
    }
    if (showSources) {
        val context = LocalContext.current
        val license = remember(context) {
            context.resources.openRawResource(R.raw.ggf_atlas_map_license).bufferedReader(Charsets.UTF_8).use { it.readText() }
        }
        AlertDialog(
            onDismissRequest = { showSources = false },
            title = { Text("지도 출처", style = GgfTheme.type.title) },
            text = {
                Column(Modifier.heightIn(max = 360.dp).verticalScroll(rememberScrollState())) {
                    Text("2026-04-01 자료를 단순화한 도감 지역 선택용 개략도입니다. " +
                        "현재 행정 경계·내비게이션·도착 판정에 사용하지 않습니다.\n\n" + license, style = GgfTheme.type.label)
                }
            },
            confirmButton = { TextButton(onClick = { showSources = false }) { Text("닫기", style = GgfTheme.type.label) } },
        )
    }
}

private data class CountryTransform(val scale: Float, val offset: Offset, val origin: Offset) {
    fun toLocal(point: Offset): Offset = (point - offset) / scale + origin
    fun toScreen(point: Offset): Offset = offset + (point - origin) * scale
}

private data class CountryLabel(
    val shape: CountryShape, val rect: Rect, val city: Boolean,
    val lines: List<String>, val fontPx: Float, val dot: Offset,
    val shortLeader: Boolean = false, val fallback: Boolean = false,
)
private data class CountryLayout(val transform: CountryTransform, val labels: List<CountryLabel>)

/** Shape extent, including every island, is fitted uniformly; no region or island is relocated. */
private val CountryBounds: Rect by lazy {
    val boxes = CountryShapes.map { it.path.getBounds() }
    Rect(boxes.minOf { it.left }, boxes.minOf { it.top }, boxes.maxOf { it.right }, boxes.maxOf { it.bottom })
}

/** Run only on size/font/region-set changes, not on every animation frame. */
private fun countryLayout(width: Float, height: Float, paint: Paint, dp: Float, known: Set<Region>): CountryLayout {
    if (width <= 0f || height <= 0f) return CountryLayout(CountryTransform(0f, Offset.Zero, Offset.Zero), emptyList())
    val bounds = CountryBounds
    val margin = 22f * dp // Also reserves room for the unchanged 16dp raised selection.
    val scale = minOf((width - margin * 2).coerceAtLeast(1f) / bounds.width,
        (height - margin * 2).coerceAtLeast(1f) / bounds.height)
    val transform = CountryTransform(scale,
        Offset((width - bounds.width * scale) / 2, (height - bounds.height * scale) / 2), bounds.topLeft)
    val shapes = CountryShapes.filter { it.region in known }
    val labels = mutableListOf<CountryLabel>()
    val cityDots = shapes.filter { it.region in CityAnchors }.associateWith {
        transform.toScreen(cityAnchor(it))
    }
    val cityPaint = Paint(paint).apply { textSize = paint.textSize * .8f }
    val letteringScale = (paint.textSize / (20f * dp)).coerceAtLeast(1f)
    val outline = 4f * dp * letteringScale
    fun metrics(lines: List<String>, font: Paint): Size = Size(
        lines.maxOf { font.measureText(it) } + outline,
        (font.descent() - font.ascent()) * lines.size + 2f * dp * (lines.size - 1) + outline,
    )
    fun clear(rect: Rect, except: CountryShape? = null): Boolean =
        rect.left >= 3f * dp && rect.top >= 3f * dp && rect.right <= width - 3f * dp && rect.bottom <= height - 3f * dp &&
            labels.none { it.rect.inflate(2f * dp).overlaps(rect) } &&
            cityDots.none { (shape, dot) -> shape != except && Rect(dot - Offset(4f * dp, 4f * dp), Size(8f * dp, 8f * dp)).overlaps(rect) }

    // Opposite placements for the two dense pairs; dot itself always stays at the geographic point.
    shapes.filter { it.region in CityAnchors }.forEach { shape ->
        val dot = cityDots.getValue(shape)
        val lines = listOf(shape.region.label)
        val size = metrics(lines, cityPaint)
        val directions = cityDirections(shape.region)
        var chosen: CountryLabel? = null
        for (gap in listOf(3f, 6f, 10f)) {
            for (direction in directions) {
                val g = gap * dp
                val x = when (direction.first) { -1 -> dot.x - size.width - g; 1 -> dot.x + g; else -> dot.x - size.width / 2 }
                val y = when (direction.second) { -1 -> dot.y - size.height - g; 1 -> dot.y + g; else -> dot.y - size.height / 2 }
                val rect = Rect(Offset(x, y), size)
                if (clear(rect, shape)) {
                    chosen = CountryLabel(shape, rect, true, lines, cityPaint.textSize, dot, shortLeader = gap > 6f)
                    break
                }
            }
            if (chosen != null) break
        }
        labels += chosen ?: CountryLabel(shape,
            Rect(Offset((dot.x - size.width / 2).coerceIn(0f, max(0f, width - size.width)),
                (dot.y - size.height - 3f * dp).coerceIn(0f, max(0f, height - size.height))), size),
            true, lines, cityPaint.textSize, dot, fallback = true)
    }

    // Place constrained provinces first; evaluate interior sites, horizontal and vertical text.
    val order = listOf(Region.CHUNGBUK, Region.GYEONGGI, Region.CHUNGNAM, Region.JEONBUK,
        Region.GYEONGNAM, Region.JEONNAM, Region.GYEONGBUK, Region.GANGWON, Region.JEJU)
    for (region in order) {
        val shape = shapes.firstOrNull { it.region == region } ?: continue
        var best: CountryLabel? = null
        var score = Float.NEGATIVE_INFINITY
        for (fontRatio in listOf(1f, .9f)) {
            val font = Paint(paint).apply { textSize = paint.textSize * fontRatio }
            for (vertical in listOf(false, true)) {
                val lines = if (vertical) shape.region.label.map { it.toString() } else listOf(shape.region.label)
                val size = metrics(lines, font)
                for (site in shape.labelSites) {
                    val centre = transform.toScreen(site)
                    val rect = Rect(centre - Offset(size.width / 2, size.height / 2), size)
                    if (!clear(rect)) continue
                    var inside = 0
                    for (fy in listOf(.15f, .5f, .85f)) for (fx in listOf(.15f, .5f, .85f)) {
                        val point = transform.toLocal(Offset(rect.left + rect.width * fx, rect.top + rect.height * fy))
                        if (shape.hit.contains(point.x.roundToInt(), point.y.roundToInt())) inside++
                    }
                    val distance = (site - shape.anchor).getDistanceSquared()
                    val value = inside * 1000f - distance * .10f - (if (vertical) 35f else 0f) - (1f - fontRatio) * 500f
                    if (value > score) {
                        score = value
                        best = CountryLabel(shape, rect, false, lines, font.textSize, centre)
                    }
                }
            }
        }
        val fallbackSize = metrics(listOf(shape.region.label), paint)
        val point = transform.toScreen(shape.anchor)
        labels += best ?: CountryLabel(shape,
            Rect(Offset((point.x - fallbackSize.width / 2).coerceIn(0f, max(0f, width - fallbackSize.width)),
                (point.y - fallbackSize.height / 2).coerceIn(0f, max(0f, height - fallbackSize.height))), fallbackSize),
            false, listOf(shape.region.label), paint.textSize, point, fallback = true)
    }

    return CountryLayout(transform, labels)
}

private fun cityAnchor(shape: CountryShape): Offset {
    val point = CityAnchors.getValue(shape.region)
    return if (shape.hit.contains(point.x.roundToInt(), point.y.roundToInt())) point else shape.anchor
}

private fun cityDirections(region: Region): List<Pair<Int, Int>> {
    val first = when (region) {
        Region.SEOUL, Region.ULSAN -> 1 to -1
        Region.INCHEON, Region.SEJONG, Region.DAEGU, Region.GWANGJU -> -1 to -1
        Region.DAEJEON, Region.BUSAN -> 1 to 1
        else -> 0 to -1
    }
    return listOf(first, 0 to -1, -1 to 0, 1 to 0, 0 to 1, -1 to -1, 1 to -1, -1 to 1, 1 to 1).distinct()
}

private val CityAnchors = mapOf(
    Region.SEOUL to Offset(269.6f, 206f), Region.INCHEON to Offset(245.4f, 213f),
    Region.SEJONG to Offset(290f, 321f), Region.DAEJEON to Offset(300.5f, 346.6f),
    Region.GWANGJU to Offset(257.5f, 483.9f), Region.DAEGU to Offset(393.2f, 389.4f),
    Region.ULSAN to Offset(442.3f, 437.7f), Region.BUSAN to Offset(428.5f, 478.8f),
)

private fun countryHit(tap: Offset, layout: CountryLayout, known: Set<Region>, dp: Float): Region? {
    layout.labels.firstOrNull { it.rect.contains(tap) }?.let { return it.shape.region }
    if (layout.transform.scale <= 0f) return null
    val local = layout.transform.toLocal(tap)
    CountryShapes.firstOrNull { it.region in known && it.hit.contains(local.x.roundToInt(), local.y.roundToInt()) }
        ?.let { return it.region }
    return layout.labels.filter { it.rect.inflate(4f * dp).contains(tap) }
        .minByOrNull { (it.rect.center - tap).getDistanceSquared() }?.shape?.region
}

private class CountryShape(
    val region: Region,
    val color: Color,
    val label: Offset,
    pathData: String,
) {
    val path: Path = PathParser().parsePathString(pathData).toPath()
    val labelSites: List<Offset> by lazy {
        val bounds = path.getBounds()
        buildList {
            var y = bounds.top + 2f
            while (y < bounds.bottom) {
                var x = bounds.left + 2f
                while (x < bounds.right) {
                    if (hit.contains(x.roundToInt(), y.roundToInt())) add(Offset(x, y))
                    x += 4f
                }
                y += 4f
            }
        }
    }
    val hit: AndroidRegion = AndroidRegion().apply {
        setPath(path.asAndroidPath(), AndroidRegion(20, 60, 670, 795))
    }
    // Pick an interior point, including island provinces whose bounding-box centre is at sea.
    val anchor: Offset by lazy {
        val centre = path.getBounds().center
        if (hit.contains(centre.x.roundToInt(), centre.y.roundToInt())) centre else {
            val iterator = RegionIterator(hit)
            val rect = AndroidRect()
            var closest = centre
            var distance = Float.POSITIVE_INFINITY
            while (iterator.next(rect)) {
                val candidate = Offset(rect.exactCenterX(), rect.exactCenterY())
                val d = (candidate - centre).getDistanceSquared()
                if (d < distance) { closest = candidate; distance = d }
            }
            closest
        }
    }
}

// Generated from U03-korea-region-selector.svg without simplifying or relocating any path.
// Each path literal is below the JVM 65535-byte constant limit. Only the app's UI labels use text.
private val CountryShapes: List<CountryShape> by lazy {
    buildCountryShapes()
}

